quests[10729] = { id = 10729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Magiers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10730] = { id = 10730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Bewahrers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10731] = { id = 10731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Auftragsmörders", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10732] = { id = 10732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des violetten Beschützers", sourceObjective = "Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, {name}? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte.\n\nDas violette Siegel wird an Macht gewinnen, wenn Ihr Euch dem violetten Auge weiterhin unter Beweis stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10733] = { id = 10733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10734] = { id = 10734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
