quests[10736] = { id = 10736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der violette Pfad", description = "Ihr habt Euren Pfad gewählt, {class}. Jetzt ist es an Euch, ihm zu folgen - wo immer er Euch auch hinführen möge.\n\nIhr werdet herausfinden, dass es seine Vorteile hat, Freunde unter den Erzmagiern von Dalaran zu haben. Dient uns wohl und Eure Taten werden nicht unbelohnt bleiben.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen wohlwollenden Ruf bei dem Violetten Auge erlangt habt.", progress = "Schön Euch wieder zu sehen, {name}.", completion = "Eure Dienste sind eine große Ehre für uns, {name}. Nun staunet, da ich die Macht in Eurem Siegelring entfesseln werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[10737] = { id = 10737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung des Meisters", description = "Ich habe den Schlüssel, den ich als Lehrling benutzt habe, wieder zusammengefügt. Er scheint völlig funktionstüchtig zu sein. Was jedoch die Öffnung von Karazhan angeht, ist er so wertlos wie ein Stück Alteisen.\n\nOhne Medivhs Einverständnis ist der Schlüssel unbrauchbar. Ja, natürlich weiß ich, dass Medivh tot ist. Das macht die Sache zwar schwieriger, aber nicht unmöglich.\n\nEs gibt einen Ort in Azeroth, der Höhlen der Zeit genannt wird. Er wird von dem bronzenen Drachenschwarm bewacht. Findet einen Weg dort hinein, reist in der Zeit zurück und bringt Medivh dazu, den Schlüssel zu aktivieren.", sourceObjective = "Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[10738] = { id = 10738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
