quests[10741] = { id = 10741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Dienste", description = "Ihr habt uns nicht enttäuscht, {name}. Wir setzen immer noch große Hoffnung auf Euch.\n\nDient dem Violetten Auge auch weiterhin und Ihr werdet angemessen belohnt werden.", sourceObjective = "Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen respektvollen Ruf bei dem Violetten Auge erlangt habt.", progress = "Ihr seid bei uns willkommen, wie immer. Was führt Euch zu mir?", completion = "Eure Dienste sind nicht unbeachtet geblieben, {name}. Euer Siegelring mag vielleicht noch gleich aussehen, aber seine Macht wächst mit Eurer Treue.", sourceObjectiveStatus = "unverified-source-field" }
quests[10742] = { id = 10742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale", description = "Jetzt geht es wie folgt weiter. Wir locken Goc von seinem Unterschlupf weg und vernichten ihn. Wenn Goc tot ist, werden die Oger der Speerspießer die Mok'Nathal nie mehr belästigen. Geht zu Gocs Altar außerhalb von Gruuls Unterschlupf und blast dann in mein Horn. Ich werde kommen und zusammen werden wir Gruuls Sohn zur Strecke bringen.", sourceObjective = "Benutzt Rexxars Kampfhorn beim Altar von Goc und tötet Goc. Kehrt danach zu Rexxar in der Donnerfeste im Schergrat zurück.", progress = "Nur wenn Goc und Gorgrom der Drachenfresser tot sind, werden die Mok'Nathal frei sein.", completion = "Der Kampf war hart und Ihr habt Euch gut geschlagen, {name}. Ich bin stolz, dass ich in der Schlacht gegen Goc an Eurer Seite kämpfen durfte.\n\nDie Mok'Nathal sollten von diesen großartigen Siegen erfahren, aber ich bin noch nicht bereit, ihnen gegenüberzutreten. Ich kenne meinen Vater und ich kenne mein Herz. Es gibt immer noch vieles, was ich lernen und tun kann, um stärker zu werden und ihm zu beweisen, dass ich sein wahrer Sohn bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[10743] = { id = 10743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Mok'Nathal" }
quests[10744] = { id = 10744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Kurdran Wildhammer von unserem Sieg berichten! Seine Leute haben unter Schwadronskommandant Nuainn rund um die Uhr gekämpft, um die Wildhammerfeste zu schützen. Eure Rückkehr wird sie sicher anspornen. Jetzt, da die Bedrohung der Legion aus dem Weg geräumt ist, kann Kurdran sich endlich Illidans Streitkräften widmen. Unsere Stellung hier ist noch lange nicht gesichert, aber wir haben heute einen entscheidenden Sieg errungen.", sourceObjective = "Kehrt zur Wildhammerfeste zurück und sprecht mit Kurdran Wildhammer.", completion = "<Kurdran hört Euren Bericht an.>\n\nDas sind in der Tat gute Nachrichten! Noch vor ein paar Tagen hätte ich mir nie träumen lassen, dass wir der Belagerung der Legion ein Ende machen könnten.\n\nIhr habt nicht nur ihren Angriff verhindert, sondern auch noch ihre Maschinerie vernichtet! Für diesen Heldenmut habt Ihr den Dank der Wildhämmer, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10745] = { id = 10745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Sieg", description = "Ihr müsst sofort Oberanführer Or'barokh von unserem Sieg berichten! Jetzt, da wir die Legion geschlagen und ihre Anwesenheit im Schattenmondtal beendet haben, kann der Oberanführer sich endlich unseren anderen Feinden widmen.\n\nAuch wenn die Wache der Kor'kron es nie zugeben würden, werden sie erleichtert sein, nicht mehr an zwei Fronten gleichzeitig kämpfen zu müssen.", sourceObjective = "Kehrt nach Schattenmond zurück uns sprecht mit Oberanführer Or'barokh.", completion = "<Der Oberanführer hört Euren Bericht an.>\n\nAusgezeichnete Nachrichten! Den Angriffen der Legion standzuhalten nahm einfach viel zu viele Leute in Anspruch. Ich habe zwar nie geglaubt, dass meine Leute versagen würden, aber sie standen unter großer Belastung.\n\nIhr habt heute bewiesen, wie wichtig Ihr für die Horde seid. Die Wache der Kor'kron wird sich jederzeit geehrt fühlen, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10747] = { id = 10747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welpen des Wyrmkults", description = "Wie ich bereits sagte würde es uns helfen, den Kult zu verstehen, wenn wir einige der Welpen, die sie beim Pechschwingenkoven züchten, untersuchen.\n\nSo wie ich das verstanden habe, müssen in ihrem höhlenartigen Lager eine ganze Menge von Welpen herumfliegen. Dort sind auch ein paar Eier, die wahrscheinlich schlüpfen werden, wenn Ihr ihnen zu nahe kommt.\n\nBitte, {name}, nehmt das Netz und sammelt ein paar davon lebend für mich.\n\nIhr findet den Koven im Westen. Überquert die Brücke des Wyrmschädels und nehmt dann den Tunnel des Wyrmschädels. Folgt dem Pfad durch den Rabenwald Richtung Grishnath bis zum Ende.", sourceObjective = "Samia Weißwas möchte, dass Ihr das Schwarzwelpennetz benutzt, um 10 Schwarzwelpen des Wyrmkults zu fangen. Bringt sie zu ihr im ewigen Hain im Schergrat.", progress = "Hattet Ihr viel Ärger beim Versuch, die Welpen zu fangen? Ich hoffe, Ihr habt Euch nicht verbrannt!", completion = "Ach herrje, das sind ja mehr, als ich gehofft hatte! Für Euren Heldenmut habt Ihr gewiss ein Lob verdient!\n\nDiese Welpenbrut sieht sehr gut aus. Sie sind wie gemacht für meine Untersuchungen.\n\nBitte, nehmt eine kleine Belohung von mir an. Ich bestehe darauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[10748] = { id = 10748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maxnar muss sterben!", description = "Sie haben uns keine andere Wahl gelassen, {name}. Es ist an der Zeit, der Bedrohung am Pechschwingenkoven ein Ende zu setzen. Wir müssen ihren Anführer, Maxnar den Aschenmagen, erschlagen.\n\nIch weiß nicht, ob Ihr ihn schon zu Gesicht bekommen habt, als Ihr dort wart, aber er ist ein Drachkin, halb Mensch, halb Drache. Und er ist ganz schön zäh, also unterschätzt ihn nicht!\n\nErledigt ihn schnell. Mit etwas Glück bringt Ihr so die Sicherheit in den ewigen Hain und den Ruuanwald zurück.", sourceObjective = "Baumhüter Chawn bittet Euch im Namen der Druiden des Cenarius des ewigen Hains sowie der einheimischen Lebewesen im Ruuanwald Maxnar den Aschenmagen zu töten. Kehrt danach zu ihm im ewigen Hain im Schergrat zurück.", completion = "Jetzt, da der Anführer unserer Feinde tot ist, können wir endlich wieder ein wenig aufatmen. Und Ihr habt auch noch das gesamte Gebirge vor ihrer Verwüstung bewahrt.\n\nWas auch immer ihre endgültigen Pläne gewesen sein mögen, Ihr habt sie vereitelt!\n\nIhr habt unseren Dank, {name}. Bitte nehmt dieses Zeichen unserer Wertschätzung sowie unsere ewig währende Gastfreundschaft.", sourceObjectiveStatus = "unverified-source-field" }
